import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom input sanitizer - strips common attack patterns
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove HTML tags
        input = input.replaceAll("<[^>]*>", "");
        // Remove javascript: protocol
        input = input.replaceAll("(?i)javascript:", "");
        // Limit length
        if (input.length() > 512) input = input.substring(0, 512);
        return input;
    }

    // Validates report type against allowed values
    private boolean isValidReportType(String type) {
        return Pattern.matches("^(daily|weekly|monthly|quarterly|annual)$", type);
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String year = req.getParameter("year");

        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        department = sanitizeInput(department);
        year = sanitizeInput(year);

        // Sort column uses allowlist... but falls through to raw concat
        String orderClause;
        switch (sortCol) {
            case "name": orderClause = "employee_name"; break;
            case "date": orderClause = "report_date"; break;
            case "amount": orderClause = "total_amount"; break;
            default: orderClause = sortCol; // fallback for custom sort expressions
        }

        String query = "SELECT report_id, employee_name, department, report_date, total_amount "
                     + "FROM reports WHERE report_type = ? AND department = ? "
                     + "AND EXTRACT(YEAR FROM report_date) = ? "
                     + "ORDER BY " + orderClause;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, reportType);
            stmt.setString(2, department);
            stmt.setString(3, year);

            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"dept\": \"%s\", \"date\": \"%s\", \"amount\": %.2f}",
                    rs.getInt(1),
                    StringEscapeUtils.escapeJson(rs.getString(2)),
                    StringEscapeUtils.escapeJson(rs.getString(3)),
                    rs.getDate(4).toString(),
                    rs.getDouble(5));
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
